          {/* Optional Scheduling Dates */}
          <fieldset className="rounded-lg p-4 space-y-3 border border-border bg-muted/50">
            <legend className="text-sm font-semibold text-foreground px-2">Scheduling (optional)</legend>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label htmlFor="planned-date" className="text-xs font-medium text-muted-foreground">Planned Date</Label>
                <Input
                  id="planned-date"
                  type="date"
                  value={form.plannedDate ? new Date(form.plannedDate).toISOString().split('T')[0] : ''}
                  onChange={(e) => updateField('plannedDate', e.target.value ? new Date(e.target.value).getTime() : undefined)}
                  placeholder="Not set"
