/**
 * Create Order Form — Dialog for creating a new customer order with optional deposit.
 *
 * Uses the shared `CustomerSelector` (see `features/customers/components/CustomerSelector`).
 */

import { useEffect, useState } from 'react'
import { Plus, Trash2 } from 'lucide-react'
import type { CreateOrderFormData, OrderLineItemForm } from '../types.js'
import { createEmptyOrderForm } from '../types.js'
import { createOrder } from '../api.js'
import { formatCentsToEuro } from '@/shared/lib/utils'
import { CustomerSelector } from '@/features/customers/components/CustomerSelector'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CreateOrderDialogProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: (orderId: string) => void
}

// ---------------------------------------------------------------------------
// Component — Line Item Row (editable)
// ---------------------------------------------------------------------------

function LineItemRow({ item, onUpdate, onRemove }: {
  item: OrderLineItemForm
  onUpdate: (updates: Partial<OrderLineItemForm>) => void
  onRemove: () => void
}) {
  const lineTypeLabels = ['part', 'labor', 'bicycle'] as const

  return (
    <div className="flex flex-col gap-1.5 p-3 border rounded-md bg-muted/20">
      {/* Line type selector */}
      <select value={item.lineType} onChange={(e) => onUpdate({ lineType: e.target.value as OrderLineItemForm['lineType'] })}
        className="h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none w-fit">
        {lineTypeLabels.map(t => <option key={t} value={t}>{t.charAt(0).toUpperCase() + t.slice(1)}</option>)}
      </select>

      {/* Description */}
      <input type="text" value={item.description} onChange={(e) => onUpdate({ description: e.target.value })} placeholder="Description"
        className="flex-1 h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none min-w-[150px]" />

      {/* Bicycle ID — shown only for bicycle line items */}
      {item.lineType === 'bicycle' && (
        <input type="text" value={item.bicycleId ?? ''} onChange={(e) => onUpdate({ bicycleId: e.target.value || null })} placeholder="Bicycle ID"
          className="h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none w-full font-mono" />
      )}

      <div className="flex items-center gap-2">
        {/* Quantity */}
        <input type="number" value={item.quantity} onChange={(e) => onUpdate({ quantity: Math.max(1, parseInt(e.target.value) || 1) })} min={1}
          className="w-16 h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none text-right" />

        {/* Unit Price (cents) */}
        <input type="number" value={item.unitPriceNet} onChange={(e) => onUpdate({ unitPriceNet: Math.max(0, parseInt(e.target.value) || 0) })} min={0} placeholder="Cents"
          className="w-24 h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none text-right font-mono" />

        {/* VAT Rate */}
        <select value={item.vatRateId} onChange={(e) => onUpdate({ vatRateId: e.target.value })}
          className="h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none">
          <option value="">VAT…</option>
        </select>

        {/* Remove button */}
        <Button variant="ghost" size="sm" onClick={onRemove} className="h-8 w-8 p-0 text-red-500 hover:text-red-700 hover:bg-red-50">
          <Trash2 className="h-4 w-4" />
        </Button>
      </div>
    </div>
  )
}

