content.text:
/**
 * Create Quote Form — Dialog for creating a new draft quote.
 *
 * Uses the shared `CustomerSelector` (see `features/customers/components/CustomerSelector`).
 * Quotes allow anonymous (walk-in) customers — `required` is NOT passed.
 */

import { useEffect, useState } from 'react'
import type { CreateQuoteFormData } from '../types.js'
import { createEmptyQuoteForm } from '../types.js'
import { createQuote } from '../api.js'
import { CustomerSelector } from '@/features/customers/components/CustomerSelector'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CreateQuoteDialogProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: (quoteId: string) => void
}

// ---------------------------------------------------------------------------
// Component — Create Quote Dialog
// ---------------------------------------------------------------------------

export function CreateQuoteDialog({ isOpen, onClose, onSuccess }: CreateQuoteDialogProps) {
  const [formData, setFormData] = useState<CreateQuoteFormData>(createEmptyQuoteForm())
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Reset form when dialog opens
  useEffect(() => {
    if (isOpen) {
      setFormData(createEmptyQuoteForm())
      setError(null)
    }
  }, [isOpen])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)

    try {
      const quote = await createQuote(formData)
      onSuccess(quote.id)
      onClose()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create quote')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>New Quote</DialogTitle>
          <DialogDescription>
            Create a new draft quote. You can add line items after creation.
          </DialogDescription>
        </DialogHeader>

        {error && (
          <div className="rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Customer Selector — shared component, walk-in allowed (no `required`) */}
          <CustomerSelector
            customerId={formData.customerId}
            onSelect={(customerId) => setFormData(prev => ({ ...prev, customerId }))}
          />

          {/* Notes */}
          <div className="space-y-2">
            <label htmlFor="notes" className="text-sm font-medium text-muted-foreground">
              Notes (optional)
            </label>
            <textarea
              id="notes"
              rows={3}
              value={formData.notes}
              onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
              placeholder="Internal notes about this quote..."
              className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 resize-none"
            />
          </div>

          {/* Total Discount */}
          <div className="space-y-2">
            <label htmlFor="totalDiscount" className="text-sm font-medium text-muted-foreground flex items-center justify-between">
              <span>Total Discount (%)</span>
              <span className="text-xs text-muted-foreground font-normal">(client-side only)</span>
            </label>
            <div className="flex items-center gap-2">
              <input
                id="totalDiscount"
                type="number"
                min={0}
                max={100}
                step={0.1}
                value={formData.totalDiscountPercent ?? ''}
                onChange={(e) => {
                  const val = e.target.value === '' ? null : parseFloat(e.target.value)
                  setFormData(prev => ({ ...prev, totalDiscountPercent: val }))
                }}
                placeholder="0"
                className="w-24 rounded-md border border-input bg-background px-3 py-2 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20"
              />
              <span className="text-sm text-muted-foreground">%</span>
            </div>
            <p className="text-xs text-muted-foreground">Applied client-side to line item totals. Not persisted to database.</p>
          </div>

          {/* Actions */}
          <DialogFooter className="gap-2 sm:gap-0">
            <Button type="button" variant="outline" onClick={onClose} disabled={submitting}>
              Cancel
            </Button>
            <Button type="submit" disabled={submitting}>
              {submitting ? 'Creating...' : 'Create Quote'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

  /** Open state controlled by parent */
  open: boolean
  /** Callback when modal opens/closes */
  onOpenChange: (open: boolean) => void
  /** Callback after successful repair creation */
  onSuccess: () => void
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function RepairIntakeModal({ open, onOpenChange, onSuccess }: RepairIntakeModalProps) {
  // Form state
  const [form, setForm] = useState<RepairIntakeFormData>(EMPTY_FORM)
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Customer search/select state
  const [customerSearch, setCustomerSearch] = useState('')
  const [allCustomers, setAllCustomers] = useState<IntakeCustomer[]>([])
  const [selectedCustomer, setSelectedCustomer] = useState<IntakeCustomer | null>(null)
  const [customerBicycles, setCustomerBicycles] = useState<IntakeBicycle[]>([])

  // Validation errors
  const [errors, setErrors] = useState<Record<string, string>>({})

  // ── Customer dropdown state (custom combobox — replaces Radix Select) ──

  const customerDropdownRef = useRef<HTMLDivElement>(null)
  const [customerIsOpen, setCustomerIsOpen] = useState(false)
  const [customerHighlightIndex, setCustomerHighlightIndex] = useState(-1)

  // ── Bicycle dropdown state (custom combobox — replaces Radix Select) ────

  const bicycleDropdownRef = useRef<HTMLDivElement>(null)
  const [bicycleIsOpen, setBicycleIsOpen] = useState(false)
  const [bicycleHighlightIndex, setBicycleHighlightIndex] = useState(-1)

  // ---------------------------------------------------------------------------
  // Effects — load customer list when modal opens
  // ---------------------------------------------------------------------------

  useEffect(() => {
    if (open) {
      loadCustomerList()
      resetForm()
    }
  }, [open])

  // Load bicycles when a customer is selected or mode changes to existing
  useEffect(() => {
    if (form.customerMode === 'existing' && form.existingCustomerId) {
      loadCustomerBicycles(form.existingCustomerId)
    } else {
      setCustomerBicycles([])
    }
  }, [form.customerMode, form.existingCustomerId])

  // ── Click-outside handler — close dropdowns when clicking outside ────────

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      const target = event.target as Node

      // Close customer dropdown if click is outside both the input and dropdown
      if (
        customerDropdownRef.current &&
        !customerDropdownRef.current.contains(target)
      ) {
        setCustomerIsOpen(false)
      }

