/**
 * RepairIntakeModal — Component tests.
 *
 * Customer selection now uses the shared `CustomerSelector` component
 * (see `features/customers/components/CustomerSelector`). The bicycle
 * dropdown continues to use a local custom combobox.
 *
 * Acceptance criteria verified:
 * - Customer search via shared component (debounced, server-side filter)
 * - Selecting a customer populates the form and triggers bicycle loading
 * - Bicycle dropdown (custom combobox) opens/closes/navigates correctly
 * - Keyboard navigation works for both dropdowns
 * - Click-outside closes the bicycle dropdown
 * - Form submission still works end-to-end
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react'
import { RepairIntakeModal } from '../RepairIntakeModal.js'

// ---------------------------------------------------------------------------
// Mock fetch for customer + bicycle API endpoints
// ---------------------------------------------------------------------------

const mockCustomers = [
  { id: 'cust-001', type: 'private' as const, displayName: 'Jane Doe', firstName: 'Jane', lastName: 'Doe', companyName: null, phone: '+32 470 123 456', email: 'jane@example.com' },
  { id: 'cust-002', type: 'company' as const, displayName: 'Acme Corp', firstName: null, lastName: null, companyName: 'Acme Corp', phone: '+32 480 987 654', email: 'info@acme.be' },
  { id: 'cust-003', type: 'private' as const, displayName: 'John Smith', firstName: 'John', lastName: 'Smith', companyName: null, phone: '+32 471 111 222', email: null },
]

const mockBicycles = [
  { id: 'bike-001', brand: 'Trek', model: 'Fuel EX', color: 'Green', year: 2023 },
  { id: 'bike-002', brand: 'Specialized', model: 'Stumpjumper', color: 'Red', year: 2022 },
]

// Track fetch calls for assertions
const originalFetch = global.fetch
const fetchCalls: Array<{ url: string; init?: RequestInit }> = []

beforeEach(() => {
  vi.clearAllMocks()
  fetchCalls.length = 0

  global.fetch = vi.fn((input: RequestInfo | URL, init?: RequestInit) => {
    const url = typeof input === 'string' ? input : String(input)
    fetchCalls.push({ url, init })

    // Shared CustomerSelector fetches with /api/customers?search=...
    if (url.startsWith('/api/customers?search=')) {
      const search = decodeURIComponent(url.split('search=')[1] || '').toLowerCase()
      const filtered = mockCustomers.filter(c =>
        c.displayName.toLowerCase().includes(search),
      )
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ customers: filtered }),
      } as Response)
    }

    if (url === '/api/customers') {
      // Bare fetch (used by shared component on mount to cache selected customer)
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ customers: mockCustomers }),
      } as Response)
    }

    if (url.startsWith('/api/repairs/customers/') || url.startsWith('/api/customers/')) {
      const customerId = url.split('/').pop()
      const customer = mockCustomers.find(c => c.id === customerId)
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({
          id: customer?.id,
          type: customer?.type,
          firstName: customer?.firstName,
          lastName: customer?.lastName,
          companyName: customer?.companyName,
          phone: customer?.phone,
          email: customer?.email,
          bicycles: mockBicycles,
        }),
      } as Response)
    }

    if (url === '/api/repairs') {
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ id: 'repair-001' }),
      } as Response)
    }

    return originalFetch(input, init)
  })
})

// ---------------------------------------------------------------------------
// Helper — render the modal with open state
// ---------------------------------------------------------------------------

function renderModal(open = true) {
  const mockOnSuccess = vi.fn()
  const mockOnOpenChange = vi.fn()

  const result = render(
    <RepairIntakeModal
      open={open}
      onOpenChange={mockOnOpenChange}
      onSuccess={mockOnSuccess}
    />
  )

  return {
    ...result,
    mockOnSuccess,
    mockOnOpenChange,
  }
}

// ---------------------------------------------------------------------------
// Helper — type a search term and wait for debounced fetch
// ---------------------------------------------------------------------------

async function searchCustomers(term: string) {
  const searchInput = screen.getByPlaceholderText(/search customers/i) as HTMLInputElement
  await act(async () => {
    fireEvent.change(searchInput, { target: { value: term } })
  })
  // Wait for debounce (250ms) + fetch to complete
  await waitFor(() => {
    expect(fetchCalls.some(c => c.url.includes(`/api/customers?search=${encodeURIComponent(term)}`))).toBe(true)
  }, { timeout: 1000 })
}

