// ---------------------------------------------------------------------------
// Test: Keyboard navigation for customer dropdown
// ---------------------------------------------------------------------------

describe('RepairIntakeModal — keyboard navigation (customer)', () => {
  it('arrow down moves highlight through customer list', async () => {
    renderModal()
    await searchCustomers('') // empty search = no results
    // Hmm, empty search won't show results in shared component.
    // Use a search that returns all
    await searchCustomers('a') // matches Jane, Acme, John (all contain 'a' or 'A')

    const searchInput = screen.getByPlaceholderText(/search customers/i)

    // Arrow down should move highlight without errors
    fireEvent.keyDown(searchInput, { key: 'ArrowDown' })

    await waitFor(() => {
      expect(screen.getByText('Jane Doe')).toBeInTheDocument()
    })
  })

  it('Enter selects the highlighted customer', async () => {
    renderModal()
    await searchCustomers('a')

    const searchInput = screen.getByPlaceholderText(/search customers/i)

    // Arrow down to highlight Jane, then Enter to select
    fireEvent.keyDown(searchInput, { key: 'ArrowDown' })
    fireEvent.keyDown(searchInput, { key: 'Enter' })

    // After selection, the dropdown closes
    await waitFor(() => {
      // Search input value resets after selection
      expect(searchInput).toBeInTheDocument()
    })
  })

  it('Escape closes the dropdown', async () => {
    renderModal()
    await searchCustomers('jane')

    const searchInput = screen.getByPlaceholderText(/search customers/i)

    // Press Escape
    fireEvent.keyDown(searchInput, { key: 'Escape' })

    // Dropdown should close — Jane Doe should not be visible
    await waitFor(() => {
      expect(screen.queryByText('Jane Doe')).not.toBeInTheDocument()
    })
  })
})

